def count_subarrays(xs):
    n = len(xs)
    if n == 0:
        return 0

    # Use prefix sums to store the cumulative sum
    # prefix_sum[i] will store the sum of xs[0]...xs[i-1]
    prefix_sum = [0] * (n + 1)
    current_sum = 0

    for i in range(n):
        current_sum += xs[i]
        prefix_sum[i + 1] = current_sum

    # Iterate through all possible subarrays
    # A subarray from index i to j (inclusive) has sum prefix_sum[j+1] - prefix_sum[i]
    # We want this sum to be equal to 6
    for j in range(n + 1):
        if prefix_sum[j] == 6:
            continue  # Skip if prefix_sum[j] is already 6, as it's not a subarray sum
        for i in range(j):
            if prefix_sum[j] - prefix_sum[i] == 6:
                return 1

    return 0
```

