def run_machine(program):
    stack = []
    for instr in program:
        if instr.startswith('PUSH'):
            stack.append(int(instr[7:]))
        elif instr == 'ADD':
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
            else:
                return -1
        elif instr == 'SUBR':
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
            else:
                return -1
        elif instr == 'DUP':
            if len(stack) >= 1:
                stack.append(stack.pop())
        elif instr == 'SWAP':
            if len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(b)
                stack.append(a)
        elif instr == 'TWIST':
            if len(stack) >= 1:
                a = stack.pop()
                stack.append(a * 3 + 1)
            else:
                return -1
        else:
            return -1

    return stack[-1] if stack else -1
```

